        await expect
          .poll(
            async () => {
              try {
                return (await fetch(url)).status;
              } catch {
                return 0;
              }
            },
            { timeout: 15000 },
          )
          .toBe(200);
        await use({ url, backend });
      } finally {
        child.kill("SIGTERM");
