  const img=page.getByRole('img',{name,exact:true});
  await img.scrollIntoViewIfNeeded();
  await img.evaluate(el=>el.decode());
  if (!(await img.evaluate(el=>el.complete && el.naturalWidth>0))) throw new Error('Attachment failed to render');
 }
 console.log('All four updated screenshots render.');
} finally {await browser.close();}
